const TTL_MS = 60_000;
const cache = new Map();

async function getQuery(query, load) {
  const saved = cache.get(query);
  if (saved && Date.now() - saved.time < TTL_MS) return saved.value;

  const value = await load(query);
  cache.set(query, { value, time: Date.now() });
  return value;
}

